// Isolation test (OS-12) — construct ObservationLedger with its declared inputs and nothing else,
// then exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown } from "../src/kernel/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import { ObservationLedger, dischargeable, score } from "../src/observation/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld, never } from "./support/fact-world.js";

const one = score(1);
if (isUnknown(one)) throw new Error("setup");
const values = { a: { value: one, author: "ENGINE" as const }, b: { value: dischargeable("later"), author: "HUMAN" as const } };

function world() {
  const w = factWorld({ currencies: ["c0"], invalidations: never });
  return { ...w, k: w.drawAt("u1" as Unit, "c0" as Currency) };
}

describe("ObservationLedger in isolation", () => {
  it("refuses to construct when an input is missing, or the components are not a list of distinct names", () => {
    const record = inMemoryRecord();
    expect(() => new ObservationLedger({ components: ["a"] } as never)).toThrow();
    expect(() => new ObservationLedger({ record } as never)).toThrow();
    expect(() => new ObservationLedger({ record, components: [] })).toThrow();
    expect(() => new ObservationLedger({ record, components: ["a", "a"] })).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new ObservationLedger({ record: {} as never, components: ["a"] })).toThrow();
  });

  it("observe answers differently when record differs", () => {
    const w = world();
    const busy = inMemoryRecord();
    busy.noise();
    const h = w.record.noise();
    expect(new ObservationLedger({ record: w.record, components: ["a", "b"] }).observe(w.k, values, "ENGINE", h)).not.toEqual(
      new ObservationLedger({ record: busy, components: ["a", "b"] }).observe(w.k, values, "ENGINE", h),
    );
  });

  it("observe answers differently when components differs", () => {
    const w = world();
    const h = w.record.noise();
    expect(new ObservationLedger({ record: w.record, components: ["a", "b"] }).observe(w.k, values, "ENGINE", h)).not.toEqual(
      new ObservationLedger({ record: w.record, components: ["a", "c"] }).observe(w.k, values, "ENGINE", h),
    );
  });

  it("observationOf answers differently when record differs", () => {
    const w = world();
    const o = new ObservationLedger({ record: w.record, components: ["a", "b"] }).observe(w.k, values, "ENGINE", w.record.noise());
    if (isUnknown(o)) throw new Error("setup");
    expect(new ObservationLedger({ record: w.record, components: ["a", "b"] }).observationOf(w.k, o.at)).not.toEqual(
      new ObservationLedger({ record: inMemoryRecord(), components: ["a", "b"] }).observationOf(w.k, o.at),
    );
  });
});
